/**
 * Translation dictionary — Thailand + ASEAN + global.
 *
 * Why 8 locales: Thailand has a multilingual workforce. Migrant workers from
 * Myanmar/Cambodia, cross-border traders with Vietnam/Indonesia, Japanese and
 * Chinese factory partners, and English as the corporate lingua franca all
 * actually touch procurement systems. Forcing them through Thai-only is the
 * single biggest accessibility regression a Thai SaaS can ship.
 *
 * Localization principles:
 *  - Keep every locale at parity with TH (compile-time check at the bottom).
 *  - Use plain, polite forms — no honorific verbosity. Same in JA (です/ます
 *    but not 致します), ZH (formal not literary).
 *  - Numbers and dates render via Intl — no localization here.
 *  - When a key starts a sentence we write the sentence start; when it's a
 *    button label we write a button (imperative).
 *
 * When you add a key:
 *   1. Add it to ALL locales. The compile-time check fails otherwise.
 *   2. Use {placeholder} for variable interpolation. See useT().
 *   3. Get a native speaker to review JA, ZH, VI, ID, MY, KM before shipping.
 *      The translations here are a competent baseline — not gospel.
 */

export const LOCALES = ['th', 'en', 'zh', 'ja', 'vi', 'id', 'my', 'km'] as const;
export type Locale = (typeof LOCALES)[number];

