export type TranslationKey = keyof typeof dictionary['th'];

// Compile-time guarantee: every locale carries the same key set.
// If you add a key to th and forget any other locale, this fails to compile.
type EnsureSameKeys = {
  [L in Locale]: (typeof dictionary)[L] extends Record<TranslationKey, string> ? true : never;
}[Locale];
const _check: EnsureSameKeys = true;
void _check;
